window.MOTIF_CATALOG_CHUNKS[6]={"cards":[{"id":"ML-T00639","row_version":4,"title":"군상 서사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00633","tag_path":[],"summary":"여러 인물의 삶과 사건을 엮어 집단이나 공동체 전체의 변화로 중심을 넓히는 구성이다. 등장인물이 많다는 수량 기준보다, 한 명의 주인공에 종속되지 않은 복수 인물의 서사적 비중을 살핀다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"군상 서사","entry_url":"cards/ML-T00639/index.html"},{"id":"ML-T00640","row_version":3,"title":"진행 방식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"이야기가 어떤 목표와 반복 원리에 따라 다음 사건이나 국면으로 이동하는지 보여주는 진행 방식이다. 시간 배열이나 전체 막 구분과 혼동하지 말고, 사건을 계속 움직이는 과제·추적·경쟁 같은 동력을 확인한다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"진행 방식","entry_url":"cards/ML-T00640/index.html"},{"id":"ML-T00641","row_version":4,"title":"퀘스트 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"주인공이 명시된 과제를 받아 여러 단계의 목표를 수행하며 진행하는 구성이다. 목표를 향한 여정이라는 넓은 의미만으로 적용하지 말고, 해결해야 할 임무나 과제가 사건 단위를 실제로 조직하는지 본다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"퀘스트 구조","entry_url":"cards/ML-T00641/index.html"},{"id":"ML-T00642","row_version":3,"title":"로드무비 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"인물들이 이동하는 경로와 그 과정에서 만나는 장소·사람·사건이 이야기의 주요 단위가 되는 구성이다. 단순한 여행 배경과 구별해, 이동 자체가 만남과 변화를 이어 붙이는 진행 원리인지 살핀다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"로드무비 구조","entry_url":"cards/ML-T00642/index.html"},{"id":"ML-T00643","row_version":4,"title":"추적 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"누군가를 뒤쫓거나 도주자를 피하는 행위가 사건을 연쇄적으로 이끄는 구성이다. 추격 장면 하나가 포함된 것보다, 거리 좁히기와 도주의 결과가 주요 전개를 좌우하는지 판단한다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"추적 구조","entry_url":"cards/ML-T00643/index.html"},{"id":"ML-T00644","row_version":3,"title":"수사 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"사건의 원인이나 범인을 밝혀내는 정보 수집과 추론이 진행의 중심이 되는 구성이다. 미스터리한 분위기만으로 분류하지 말고, 단서의 검토와 가설 수정이 해결까지 사건을 조직하는지 본다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"수사 구조","entry_url":"cards/ML-T00644/index.html"},{"id":"ML-T00645","row_version":3,"title":"토너먼트 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"참가자들이 차례로 맞붙고 승자가 다음 단계로 진출하는 경쟁을 중심으로 사건을 배열하는 구성이다. 대회가 배경으로만 존재하는 경우와 구별해, 대진과 탈락·진출이 이야기의 주요 진행을 정하는지 살핀다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"토너먼트 구조","entry_url":"cards/ML-T00645/index.html"},{"id":"ML-T00646","row_version":3,"title":"미션 반복 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"비슷한 형식의 임무를 반복 수행하며 각 임무의 결과가 다음 상황으로 이어지는 구성이다. 반복되는 에피소드가 있다는 사실만으로 보지 말고, 임무 수행이 지속적인 목표나 상태 변화를 만들어내는지 확인한다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"미션 반복 구조","entry_url":"cards/ML-T00646/index.html"},{"id":"ML-T00647","row_version":3,"title":"단계 상승 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00640","tag_path":[],"summary":"장애와 대결의 규모나 난도가 차례로 커지며 더 높은 국면으로 진행되는 구성이다. 사건이 여러 번 벌어지는 것과 구별해, 뒤의 도전이 앞선 단계보다 더 큰 위험이나 능력을 요구하는지 본다.","accent":"#6A748C","tab":"#528982","facet":"서사 구조","bookmark":"단계 상승 구조","entry_url":"cards/ML-T00647/index.html"},{"id":"ML-T00648","row_version":4,"title":"시작 방식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"이야기가 어느 지점이나 상황에서 독자·관객에게 처음 제시되는지를 정하는 방식이다. 시작 시점의 선택과 전체 사건의 시간 배열을 구분해, 첫 장면이 어떤 정보와 기대를 설정하는지 살핀다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"시작 방식","entry_url":"cards/ML-T00648/index.html"},{"id":"ML-T00649","row_version":3,"title":"일상에서 시작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00648","tag_path":[],"summary":"큰 갈등이 드러나기 전 인물의 평소 생활이나 익숙한 세계를 보여주며 이야기를 여는 방식이다. 일상 묘사가 길다는 이유만으로 보지 말고, 뒤의 변화가 무엇을 깨뜨리는지 이해할 기준을 마련하는지 판단한다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"일상에서 시작","entry_url":"cards/ML-T00649/index.html"},{"id":"ML-T00650","row_version":3,"title":"사건 한가운데서 시작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00648","tag_path":[],"summary":"이미 진행 중인 위기나 행동의 한복판에서 이야기를 시작하는 방식이다. 단순히 첫 장면이 빠르거나 긴박한 것과 달리, 사건의 발단을 뒤로 미루고 진행 중인 상황부터 제시하는지 본다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"사건 한가운데서 시작","entry_url":"cards/ML-T00650/index.html"},{"id":"ML-T00651","row_version":2,"title":"결말 선공개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00648","tag_path":[],"summary":"이야기의 최종 결과나 결말 장면을 먼저 보여준 뒤 그 결과에 이르는 과정을 제시하는 방식이다. 결말을 암시하는 복선이나 미래의 짧은 예고와 구별해, 실제 종착점에 해당하는 장면이 초반에 제시되는지 살핀다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"결말 선공개","entry_url":"cards/ML-T00651/index.html"},{"id":"ML-T00652","row_version":5,"title":"프롤로그 분리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00648","tag_path":[],"summary":"본편에 앞서 별도의 시간·인물·사건을 다루는 도입부를 두고 본편의 시작과 구획하는 방식이다. 첫 장면이 본편과 분위기만 다르다고 보지 말고, 프롤로그가 본편과 구별되는 서사 단위로 기능하는지 본다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"프롤로그 분리","entry_url":"cards/ML-T00652/index.html"},{"id":"ML-T00653","row_version":5,"title":"출생에서 시작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00648","tag_path":[],"summary":"주인공의 출생이나 탄생을 이야기의 첫 사건으로 삼아 삶의 흐름을 시작하는 방식이다. 출생 장면이 잠깐 언급되는 것과 구별해, 이후 서사가 그 인물의 성장과 생애를 따라가는지 판단한다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"출생에서 시작","entry_url":"cards/ML-T00653/index.html"},{"id":"ML-T00654","row_version":4,"title":"귀환에서 시작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00648","tag_path":[],"summary":"주인공이 어떤 여정이나 부재 뒤에 돌아오는 장면에서 이야기를 시작하는 방식이다. 귀환이 단순한 과거 정보가 아니라 현재의 갈등을 여는 출발점으로 기능하는지 살핀다.","accent":"#6A748C","tab":"#7D8FA3","facet":"서사 구조","bookmark":"귀환에서 시작","entry_url":"cards/ML-T00654/index.html"},{"id":"ML-T00655","row_version":3,"title":"종결 방식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"주요 사건과 갈등이 어떤 형태로 끝나는지를 정하는 마무리 방식이다. 마지막 장면의 분위기만으로 판단하지 말고, 핵심 질문의 해결 여부와 종결 뒤에 남는 가능성을 기준으로 삼는다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"종결 방식","entry_url":"cards/ML-T00655/index.html"},{"id":"ML-T00656","row_version":3,"title":"닫힌 결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"주요 갈등과 핵심 질문에 분명한 답을 주어 사건의 큰 줄기를 마무리하는 결말이다. 모든 인물의 미래까지 설명할 필요는 없지만, 중심 문제의 해결 여부가 작품 안에서 판별되는지 본다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"닫힌 결말","entry_url":"cards/ML-T00656/index.html"},{"id":"ML-T00657","row_version":3,"title":"열린 결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"중심 갈등의 일부를 남기거나 이후의 선택을 미정으로 두어 해석과 상상을 이어가게 하는 결말이다. 단순히 설명이 부족하거나 갑자기 끝난 것과 구별해, 미해결 상태가 의미 있는 여지를 만드는지 판단한다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"열린 결말","entry_url":"cards/ML-T00657/index.html"},{"id":"ML-T00658","row_version":2,"title":"순환 결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"마지막의 장면·상황·이미지가 시작 부분과 맞물려 이야기를 고리처럼 닫는 결말이다. 같은 요소가 다시 등장하기만 하는 것은 부족하며, 반복이 처음과 끝의 관계나 변화된 의미를 드러내는지 본다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"순환 결말","entry_url":"cards/ML-T00658/index.html"},{"id":"ML-T00659","row_version":3,"title":"반전 결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"마지막 정보나 사건이 앞선 이해를 뒤집거나 새롭게 해석하게 만드는 결말이다. 놀라움이나 예상 밖의 사건만으로 적용하지 말고, 반전이 기존 단서와 이야기의 의미를 재구성하는지 살핀다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"반전 결말","entry_url":"cards/ML-T00659/index.html"},{"id":"ML-T00660","row_version":3,"title":"해피엔딩","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"주요 인물의 목표나 관계가 긍정적인 결과에 이르는 결말이다. 고난이 끝나거나 분위기가 밝다는 이유만으로 단정하지 말고, 중심 갈등의 귀결이 인물에게 실제로 만족스러운지 본다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"해피엔딩","entry_url":"cards/ML-T00660/index.html"},{"id":"ML-T00661","row_version":4,"title":"비극적 결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"비극적 결말은 중심 인물이나 공동체가 중대한 상실·파멸을 맞거나, 갈등이 회복하기 어려운 피해로 끝나는 종결이다. 인물의 죽음만으로 판단하지 말고 마지막 결과가 작품의 핵심 갈등과 인물의 선택을 어떻게 마무리하는지 살핀다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"비극적 결말","entry_url":"cards/ML-T00661/index.html"},{"id":"ML-T00662","row_version":3,"title":"씁쓸한 승리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"씁쓸한 승리는 목표를 이루거나 위협을 물리치지만, 그 대가로 중요한 관계·가치·자원을 잃는 결말이다. 승리와 손실이 모두 서사의 결과로 남아야 하며, 단순한 실패나 승리 뒤의 일시적 불편과 구별한다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"씁쓸한 승리","entry_url":"cards/ML-T00662/index.html"},{"id":"ML-T00663","row_version":2,"title":"결말 유예","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00655","tag_path":[],"summary":"결말 유예는 주요 갈등이나 목표의 최종 해결을 뒤로 미뤄 이야기를 열린 상태로 끝내는 방식이다. 미해결 요소가 후속 전개를 기다리는 핵심 문제인지, 부차적 의문만 남긴 완결된 결말인지 구분한다.","accent":"#6A748C","tab":"#A07A87","facet":"서사 구조","bookmark":"결말 유예","entry_url":"cards/ML-T00663/index.html"},{"id":"ML-T00664","row_version":3,"title":"연속성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"연속성은 여러 에피소드나 작품의 사건·인물·세계 상태가 이어져 앞선 전개가 뒤의 이야기에도 유효하게 작용하는 구성 원리다. 같은 인물이나 배경이 반복된다는 사실만으로는 부족하며, 사건의 결과가 공유되는지를 기준으로 판단한다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"연속성","entry_url":"cards/ML-T00664/index.html"},{"id":"ML-T00665","row_version":3,"title":"독립 에피소드","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"독립 에피소드는 각 회차의 중심 갈등이 그 회차 안에서 주로 시작되고 해결되어, 순서를 바꾸거나 일부를 건너뛰어도 전체 줄거리 이해가 크게 달라지지 않는 구성이다. 반복 등장하는 설정이나 인물의 작은 변화는 허용되지만, 회차 간 사건 의존이 핵심이면 해당하지 않는다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"독립 에피소드","entry_url":"cards/ML-T00665/index.html"},{"id":"ML-T00666","row_version":3,"title":"시즌 아크","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"시즌 아크는 한 시즌을 범위로 삼아 여러 회차에 걸쳐 진행되는 갈등이나 목표의 흐름이다. 회차별 사건이 독립적으로 끝나더라도 시즌 차원의 변화와 결말을 위해 서로 누적되는지 살핀다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"시즌 아크","entry_url":"cards/ML-T00666/index.html"},{"id":"ML-T00667","row_version":4,"title":"장기 아크","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"장기 아크는 여러 시즌이나 작품을 가로질러 인물의 변화, 갈등 또는 목표가 단계적으로 전개되는 서사 흐름이다. 단순히 작품이 오래 이어지는 경우와 달리, 초기 사건이 훗날의 전개나 최종 해결에 의미 있게 연결되어야 한다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"장기 아크","entry_url":"cards/ML-T00667/index.html"},{"id":"ML-T00668","row_version":3,"title":"전일담","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"전일담은 이미 알려진 본편의 사건보다 앞선 시기를 다루며, 인물이나 상황이 본편의 출발점에 이르는 과정을 보여주는 이야기다. 과거를 배경으로 한 독립 이야기와 구별하려면 본편과 인물·사건의 연결이 핵심이어야 한다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"전일담","entry_url":"cards/ML-T00668/index.html"},{"id":"ML-T00669","row_version":4,"title":"후속담","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"후속담은 앞선 이야기의 시간적 뒤를 이어 인물과 세계가 이후에 겪는 사건을 다룬다. 같은 세계관만 공유하는 별도 이야기가 아니라, 본편에서 비롯된 상황이나 변화가 후속 전개의 바탕인지 확인한다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"후속담","entry_url":"cards/ML-T00669/index.html"},{"id":"ML-T00670","row_version":4,"title":"외전","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"외전은 본편의 중심 줄거리 바깥에서 같은 세계나 인물군을 활용해 별도의 사건·관점·시기를 다루는 이야기다. 본편의 직접적인 다음 사건을 이어 해결하는 후속담과 구별해, 중심 서사와의 거리 및 보충 기능을 살핀다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"외전","entry_url":"cards/ML-T00670/index.html"},{"id":"ML-T00671","row_version":4,"title":"스핀오프 서사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00664","tag_path":[],"summary":"스핀오프 서사는 기존 작품의 조연·설정·세계 일부를 중심으로 삼아 별도의 주인공과 이야기 흐름을 전개한다. 같은 세계를 배경으로 한다는 점만으로 분류하지 말고, 기존 작품의 특정 요소가 새 서사의 중심을 이루는지 판단한다.","accent":"#6A748C","tab":"#79866C","facet":"서사 구조","bookmark":"스핀오프 서사","entry_url":"cards/ML-T00671/index.html"},{"id":"ML-T00672","row_version":3,"title":"소개·정위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"이야기의 시작에서 독자가 세계와 상황을 파악하도록 기본 좌표를 마련하는 기능이다. 배경이나 규칙 하나만 제시하는 장면보다 여러 정보로 서사의 출발점을 세우는 경우에 적용한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"소개·정위","entry_url":"cards/ML-T00672/index.html"},{"id":"ML-T00673","row_version":3,"title":"세계 소개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00672","tag_path":[],"summary":"장소와 시대, 사회 질서처럼 인물이 살아가는 환경을 알려 이야기의 무대를 세운다. 개별 인물의 성격이나 사건의 규칙보다 생활 조건과 세계의 구조를 드러내는 데 초점을 둔다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"세계 소개","entry_url":"cards/ML-T00673/index.html"},{"id":"ML-T00674","row_version":2,"title":"인물 소개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00672","tag_path":[],"summary":"인물의 외모, 처지, 성격, 역할 등 이후 행동을 이해하는 데 필요한 특징을 처음 드러낸다. 이미 아는 인물의 숨은 면모가 밝혀지는 경우는 단순한 첫 소개와 구분한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"인물 소개","entry_url":"cards/ML-T00674/index.html"},{"id":"ML-T00675","row_version":2,"title":"관계 소개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00672","tag_path":[],"summary":"인물 사이의 친족·동료·대립 같은 연결과 각자의 위치를 보여 준다. 각 인물을 따로 소개하는 데 그치지 않고 둘 이상의 관계가 관객에게 파악되도록 해야 한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"관계 소개","entry_url":"cards/ML-T00675/index.html"},{"id":"ML-T00676","row_version":3,"title":"규칙 제시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00672","tag_path":[],"summary":"세계나 사건이 따르는 조건과 한계를 제시해 가능한 행동과 결과를 이해시키는 기능이다. 일반적인 배경 설명이 아니라 이후 선택이나 사건의 성립을 좌우할 규칙이 드러날 때 적용한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"규칙 제시","entry_url":"cards/ML-T00676/index.html"},{"id":"ML-T00677","row_version":3,"title":"목표 제시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00672","tag_path":[],"summary":"주인공이나 주요 인물이 이루려는 상태를 드러내 서사의 진행 방향을 잡는다. 당장의 행동이나 필요만 언급되고 도달하려는 결과가 특정되지 않으면 목표 제시로 보지 않는다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"목표 제시","entry_url":"cards/ML-T00677/index.html"},{"id":"ML-T00678","row_version":2,"title":"분위기 설정","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00672","tag_path":[],"summary":"공간, 행동, 표현의 정조를 통해 작품을 어떤 감각과 정서로 받아들일지 설정한다. 특정 장면의 일시적 감정보다 여러 장면에 이어지는 전반적 분위기를 형성할 때 적용한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분위기 설정","entry_url":"cards/ML-T00678/index.html"},{"id":"ML-T00679","row_version":3,"title":"발동·추진","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"정체된 상황을 흔들거나 다음 행동을 잇달아 일으켜 서사를 움직이는 기능이다. 출발점이 되는 사건부터 이미 진행 중인 목표의 수정까지, 이야기의 방향이나 추진력이 달라지는 경우를 포함한다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"발동·추진","entry_url":"cards/ML-T00679/index.html"},{"id":"ML-T00680","row_version":3,"title":"사건 촉발","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00679","tag_path":[],"summary":"이전의 균형을 깨는 사건이 발생해 인물의 대응과 이야기의 전개를 시작한다. 사건이 등장해도 인물의 상황이나 행동 가능성에 실질적 변화가 없다면 촉발 기능은 약하다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"사건 촉발","entry_url":"cards/ML-T00680/index.html"},{"id":"ML-T00681","row_version":3,"title":"모험의 부름","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00679","tag_path":[],"summary":"익숙한 환경을 떠나 새로운 임무나 미지의 여정에 나서라는 요구가 주어진다. 단순히 사건이 터지는 것과 달리, 인물이 기존 생활권을 벗어날 제안이나 필요를 받는 구조에 적용한다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"모험의 부름","entry_url":"cards/ML-T00681/index.html"},{"id":"ML-T00682","row_version":4,"title":"동기 부여","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00679","tag_path":[],"summary":"인물이 특정 행동이나 목표를 선택할 이유를 사건, 욕구, 책임 또는 감정으로 구체화한다. 행동이 일어났다는 사실만으로는 부족하며 그 행동을 낳은 이유가 서사에 드러나야 한다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"동기 부여","entry_url":"cards/ML-T00682/index.html"},{"id":"ML-T00683","row_version":2,"title":"목표 갱신","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00679","tag_path":[],"summary":"새로운 사실이나 상황 변화 때문에 인물이 추구하는 결과가 달라지거나 더 구체적으로 조정된다. 기존 목표를 단순히 반복하거나 같은 목표의 진행 단계만 추가하는 경우와 구분한다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"목표 갱신","entry_url":"cards/ML-T00683/index.html"},{"id":"ML-T00684","row_version":3,"title":"행동 강제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00679","tag_path":[],"summary":"외부의 명령, 위기, 제약이 인물의 선택지를 좁혀 어떤 행동을 하도록 몰아간다. 인물이 스스로 의욕을 내는 동기 부여와 달리, 행동하지 않을 자유나 여유가 실질적으로 제한되는 데 초점을 둔다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"행동 강제","entry_url":"cards/ML-T00684/index.html"},{"id":"ML-T00685","row_version":2,"title":"선택 압박","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00679","tag_path":[],"summary":"서로 양립하기 어려운 선택지를 맞세워 결정의 비용과 압박을 키운다. 단순히 시간이 부족하거나 위험이 닥친 장면보다, 어느 쪽을 택해도 포기하거나 감수할 것이 분명해야 한다.","accent":"#88734E","tab":"#778F70","facet":"서사 기능","bookmark":"선택 압박","entry_url":"cards/ML-T00685/index.html"},{"id":"ML-T00686","row_version":3,"title":"긴장·속도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"장면과 사건의 배열을 조절해 관객이 느끼는 압박과 서술의 진행 속도를 다룬다. 긴장을 높이거나 낮추는 효과와 전개 속도의 변화를 구분해, 실제로 조정되는 요소를 기준으로 적용한다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"긴장·속도","entry_url":"cards/ML-T00686/index.html"},{"id":"ML-T00687","row_version":2,"title":"긴장 상승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00686","tag_path":[],"summary":"위험, 불확실성, 갈등이 커지면서 다음 결과에 대한 불안과 주의가 높아진다. 단순히 상황이 더 시끄럽거나 복잡해지는 것보다 실패의 대가나 임박성이 커져야 한다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"긴장 상승","entry_url":"cards/ML-T00687/index.html"},{"id":"ML-T00688","row_version":2,"title":"긴장 지연","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00686","tag_path":[],"summary":"결정적 결과나 해결을 바로 보여 주지 않고 정보나 행동을 늦춰 궁금증과 불안을 이어 간다. 장면이 길다는 이유만으로 해당하지 않으며, 미뤄진 대상에 대한 기대나 걱정이 유지되어야 한다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"긴장 지연","entry_url":"cards/ML-T00688/index.html"},{"id":"ML-T00689","row_version":2,"title":"긴장 완화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00686","tag_path":[],"summary":"위험의 일시적 해소, 안전한 상호작용, 유머 등으로 축적된 압박을 낮춘다. 갈등이 끝나 긴장이 영구히 해소되는 결말과 달리, 이후 다시 높아질 수 있는 국면의 완화에 적용한다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"긴장 완화","entry_url":"cards/ML-T00689/index.html"},{"id":"ML-T00690","row_version":3,"title":"속도 가속","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00686","tag_path":[],"summary":"사건을 빠르게 잇거나 설명과 간격을 줄여 전개가 더 빠르게 느껴지도록 한다. 긴박한 분위기만으로 판단하지 말고, 실제 장면 길이·전환·행동의 밀도가 높아졌는지 살핀다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"속도 가속","entry_url":"cards/ML-T00690/index.html"},{"id":"ML-T00691","row_version":2,"title":"속도 감속","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00686","tag_path":[],"summary":"행동 사이에 머무름이나 설명, 관찰의 시간을 두어 전개가 느긋해지도록 한다. 긴장감이 낮다는 뜻과 같지 않으며, 위기 중에도 세부 관찰과 짧은 지연으로 속도는 감속될 수 있다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"속도 감속","entry_url":"cards/ML-T00691/index.html"},{"id":"ML-T00692","row_version":2,"title":"위협 예고","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00686","tag_path":[],"summary":"아직 벌어지지 않은 위험의 징후나 가능성을 보여 주어 이후의 불안을 준비한다. 위협이 이미 실제 피해로 발생한 장면이나 막연한 불길함과 달리, 미래의 위험을 가리키는 단서가 있어야 한다.","accent":"#88734E","tab":"#8B739C","facet":"서사 기능","bookmark":"위협 예고","entry_url":"cards/ML-T00692/index.html"},{"id":"ML-T00693","row_version":3,"title":"인물 변화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"사건과 선택의 누적이 인물의 태도, 판단, 행동 방식에 의미 있는 변화를 일으킨다. 일시적인 감정이나 겉모습의 변화보다 이후의 선택에도 이어지는 내적·행동적 차이를 기준으로 삼는다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"인물 변화","entry_url":"cards/ML-T00693/index.html"},{"id":"ML-T00694","row_version":2,"title":"성장 계기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00693","tag_path":[],"summary":"인물이 새로운 능력이나 통찰을 얻고 성장하도록 요구하는 경험이나 도전이 주어진다. 성장의 결과 자체보다 그것을 촉진한 계기와 인물의 이전 한계를 넘으려는 과정에 초점을 둔다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"성장 계기","entry_url":"cards/ML-T00694/index.html"},{"id":"ML-T00695","row_version":2,"title":"결핍 드러내기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00693","tag_path":[],"summary":"인물이 스스로 외면하거나 주변에 감춰 온 약점, 욕구, 부족함이 행동과 결과를 통해 드러난다. 단순한 실수나 능력 부족이 아니라 판단과 관계에 영향을 주는 지속적 결핍이 확인되어야 한다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"결핍 드러내기","entry_url":"cards/ML-T00695/index.html"},{"id":"ML-T00696","row_version":2,"title":"신념 시험","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00693","tag_path":[],"summary":"압박이나 유혹이 인물의 신념을 실제 행동으로 지킬 수 있는지 시험한다. 인물이 자신의 믿음을 말하는 장면과 달리, 그 믿음을 따를 때 치를 대가나 포기할 이익이 걸려 있어야 한다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"신념 시험","entry_url":"cards/ML-T00696/index.html"},{"id":"ML-T00697","row_version":2,"title":"각성 계기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00693","tag_path":[],"summary":"중대한 경험이나 깨달음이 인물의 인식과 행동을 바꾸어 새로운 가능성을 열어 준다. 단순한 정보 습득이나 순간적 감정 고양보다 이후의 판단과 선택에서 변화가 확인되어야 한다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"각성 계기","entry_url":"cards/ML-T00697/index.html"},{"id":"ML-T00698","row_version":2,"title":"타락 계기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00693","tag_path":[],"summary":"두려움, 욕망, 권력 또는 상처가 인물을 점차 부정한 선택으로 이끄는 전환점이 생긴다. 나쁜 행동 한 번만으로 판단하지 말고, 도덕적 선이나 기존 원칙에서 이탈하는 원인과 방향을 살핀다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"타락 계기","entry_url":"cards/ML-T00698/index.html"},{"id":"ML-T00699","row_version":2,"title":"정체성 확인","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00693","tag_path":[],"summary":"압박이나 선택을 거치며 인물이 자신이 누구인지, 무엇을 지킬 것인지 확인하고 그에 맞는 행동을 한다. 타인이 정체를 밝혀 주는 정보 공개와 달리, 인물의 자기 인식이나 소속에 대한 입장이 드러나야 한다.","accent":"#88734E","tab":"#A58A4E","facet":"서사 기능","bookmark":"정체성 확인","entry_url":"cards/ML-T00699/index.html"},{"id":"ML-T00700","row_version":3,"title":"관계 변화 유도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"사건과 상호작용이 인물 사이의 거리, 권력, 애착 또는 신뢰를 바꾸도록 작동한다. 관계 변화의 구체적 방향이 가까워짐인지 균열인지 역전인지 구분해 세부 기능을 적용한다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"관계 변화 유도","entry_url":"cards/ML-T00700/index.html"},{"id":"ML-T00701","row_version":2,"title":"친밀감 형성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00700","tag_path":[],"summary":"공유한 경험과 배려, 상호 개방을 통해 인물 사이의 정서적 거리가 가까워진다. 함께 등장하거나 협력하는 것만으로는 충분하지 않으며, 서로를 향한 이해나 애착이 늘어나는 근거가 있어야 한다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"친밀감 형성","entry_url":"cards/ML-T00701/index.html"},{"id":"ML-T00702","row_version":2,"title":"신뢰 시험","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00700","tag_path":[],"summary":"위기나 정보의 불균형 속에서 한 인물이 다른 인물을 믿고 맡길 수 있는지 드러난다. 믿음이 생기는 과정과 달리, 이미 존재하는 신뢰의 강도나 한계를 확인하는 상황에 적용한다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"신뢰 시험","entry_url":"cards/ML-T00702/index.html"},{"id":"ML-T00703","row_version":3,"title":"관계 균열","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00700","tag_path":[],"summary":"갈등, 비밀, 이해 충돌이 관계의 안정성을 깨고 불신이나 거리감을 만든다. 단순한 말다툼보다 서로의 협력이나 친밀감이 손상되거나 흔들리는 효과가 있어야 한다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"관계 균열","entry_url":"cards/ML-T00703/index.html"},{"id":"ML-T00704","row_version":3,"title":"배신 드러내기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00700","tag_path":[],"summary":"가까운 인물이 숨겨 온 배반이나 적대 행위가 밝혀져 관계와 사건의 해석이 달라진다. 의심이 생기거나 배신이 새로 일어나는 장면과 달리, 기존 행위의 진상이 드러나는 데 초점을 둔다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"배신 드러내기","entry_url":"cards/ML-T00704/index.html"},{"id":"ML-T00705","row_version":2,"title":"화해 유도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00700","tag_path":[],"summary":"사과, 이해, 공동의 행동을 통해 멀어진 인물들이 관계를 회복할 계기를 마련한다. 갈등의 원인이 잠시 중단된 것만으로는 부족하며, 양쪽이 관계를 다시 이어 갈 움직임이 나타나야 한다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"화해 유도","entry_url":"cards/ML-T00705/index.html"},{"id":"ML-T00706","row_version":2,"title":"관계 역전","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00700","tag_path":[],"summary":"정보나 힘의 변화로 관계에서 우위에 있던 인물과 의존하던 인물의 위치가 뒤바뀐다. 단순한 승패의 변화가 아니라 이후의 상호작용에서 권한이나 주도권이 바뀌는 경우에 적용한다.","accent":"#88734E","tab":"#528982","facet":"서사 기능","bookmark":"관계 역전","entry_url":"cards/ML-T00706/index.html"},{"id":"ML-T00707","row_version":3,"title":"정보·인지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"누가 무엇을 알고 믿는지, 관객이 무엇을 파악하는지를 배치해 이야기의 이해를 조절한다. 정보의 양을 늘리는 데 그치지 않고, 인물과 관객 사이의 앎의 차이나 해석 변화가 서사에 영향을 줄 때 적용한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"정보·인지","entry_url":"cards/ML-T00707/index.html"},{"id":"ML-T00708","row_version":3,"title":"복선 설치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00707","tag_path":[],"summary":"나중에 의미가 밝혀질 단서나 반복 요소를 앞서 배치해 미래의 사건과 연결할 가능성을 만든다. 분위기를 위한 세부 묘사와 달리, 후속 전개에서 회수되거나 재해석될 실마리가 기능해야 한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"복선 설치","entry_url":"cards/ML-T00708/index.html"},{"id":"ML-T00709","row_version":3,"title":"복선 회수","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00707","tag_path":[],"summary":"앞서 제시한 단서의 의미를 후속 사건이 밝혀 주거나 완성해 관객의 인식을 갱신한다. 이전 장면과의 연결이 성립하지 않는 우연한 발견이나 새로운 정보의 공개와 구분한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"복선 회수","entry_url":"cards/ML-T00709/index.html"},{"id":"ML-T00710","row_version":2,"title":"오해 유발","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00707","tag_path":[],"summary":"불완전한 정보나 엇갈린 해석으로 인물 또는 관객이 사실과 다른 결론을 내리게 한다. 단순히 정보를 모르는 상태가 아니라, 잘못된 판단을 뒷받침하는 단서나 오독 과정이 있어야 한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"오해 유발","entry_url":"cards/ML-T00710/index.html"},{"id":"ML-T00711","row_version":2,"title":"진실 공개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00707","tag_path":[],"summary":"감춰져 있거나 잘못 이해되던 사실을 밝혀 인물과 관객의 지식 상태를 바꾼다. 새 정보의 제시가 아니라 이전의 의문, 거짓 믿음, 비밀 가운데 무엇을 확정하는지 짚어 적용한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"진실 공개","entry_url":"cards/ML-T00711/index.html"},{"id":"ML-T00712","row_version":3,"title":"관점 전환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00707","tag_path":[],"summary":"초점 인물이나 서술의 관점이 바뀌어 같은 사건이나 세계를 다른 위치에서 보게 한다. 장면 장소만 옮기는 전환과 달리, 정보 접근과 해석을 결정하는 시점 또는 관찰자가 달라져야 한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"관점 전환","entry_url":"cards/ML-T00712/index.html"},{"id":"ML-T00713","row_version":2,"title":"기대 형성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00707","tag_path":[],"summary":"반복, 약속, 미해결 문제를 통해 관객이 이후 특정 사건이나 결과를 기다리게 만든다. 단순히 다음 장면이 궁금한 상태보다, 작품이 무엇을 기대하도록 유도하는지가 구체적이어야 한다.","accent":"#88734E","tab":"#7D8FA3","facet":"서사 기능","bookmark":"기대 형성","entry_url":"cards/ML-T00713/index.html"},{"id":"ML-T00714","row_version":2,"title":"의미·효과","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"장면과 표현이 이야기에 정서적·해석적 의미를 더하거나 관객에게 특정한 효과를 만든다. 작가의 의도를 추정하기보다 작품 안에서 반복되거나 강조된 요소가 실제로 수행하는 기능을 기준으로 한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"의미·효과","entry_url":"cards/ML-T00714/index.html"},{"id":"ML-T00715","row_version":3,"title":"주제 강조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"선택과 사건을 통해 작품이 다루는 핵심 질문이나 가치 판단을 부각한다. 인물이 주제를 직접 말하는 장면뿐 아니라 결과와 대비가 그 문제를 선명하게 만들 때도 적용한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"주제 강조","entry_url":"cards/ML-T00715/index.html"},{"id":"ML-T00716","row_version":2,"title":"가치 대비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"서로 다른 가치나 태도를 나란히 놓아 차이와 충돌을 드러낸다. 두 대상이 단지 다르기만 한 경우보다, 그 차이가 선택의 의미나 작품의 판단에 영향을 줄 때 해당한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"가치 대비","entry_url":"cards/ML-T00716/index.html"},{"id":"ML-T00717","row_version":2,"title":"상징 강화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"사물, 이미지, 행동의 반복이나 맥락 변화로 상징이 가리키는 의미를 선명하게 한다. 반복만으로 상징이라고 단정하지 말고, 구체적 대상 너머의 생각이나 감정과 연결되는 단서를 확인한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"상징 강화","entry_url":"cards/ML-T00717/index.html"},{"id":"ML-T00718","row_version":2,"title":"풍자 기능","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"과장, 모순, 아이러니를 이용해 권력이나 관습, 사회적 태도의 허점을 웃음과 비판으로 드러낸다. 단순한 농담이나 악인 조롱이 아니라 비판의 대상과 표현 방식이 연결되어야 한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"풍자 기능","entry_url":"cards/ML-T00718/index.html"},{"id":"ML-T00719","row_version":2,"title":"감정 이입","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"관객이 인물의 감정과 처지를 이해하거나 자신의 감정처럼 따라 느끼게 한다. 인물이 화면에 오래 등장하는 것보다 감정의 원인과 반응이 관객에게 읽히는지가 기준이다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"감정 이입","entry_url":"cards/ML-T00719/index.html"},{"id":"ML-T00720","row_version":2,"title":"웃음 유발","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"대사, 행동, 상황의 불일치나 예상 밖의 전환으로 웃음을 일으킨다. 가벼운 분위기만으로는 해당하지 않으며, 웃음이 생기는 표현이나 상황의 구조를 특정할 수 있어야 한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"웃음 유발","entry_url":"cards/ML-T00720/index.html"},{"id":"ML-T00721","row_version":3,"title":"여운 형성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00714","tag_path":[],"summary":"사건이 끝난 뒤에도 이미지, 감정, 질문이 관객에게 남도록 마무리나 여백을 구성한다. 결말이 열려 있다는 사실만으로는 부족하며, 남겨진 요소가 지속적인 정서나 해석을 유도해야 한다.","accent":"#88734E","tab":"#A07A87","facet":"서사 기능","bookmark":"여운 형성","entry_url":"cards/ML-T00721/index.html"},{"id":"ML-T00722","row_version":3,"title":"해소·연결","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"group","parent_id":"ML-F06","tag_path":[],"summary":"해소·연결은 사건의 긴장을 정리하거나 결과를 제시하면서 이야기를 다음 국면으로 잇는 서술상의 움직임이다. 작품에 적용할 때는 한 장면의 결말뿐 아니라 그 결과가 인물과 이후 전개에 미치는 역할을 함께 살핀다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"해소·연결","entry_url":"cards/ML-T00722/index.html"},{"id":"ML-T00723","row_version":2,"title":"갈등 해소","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00722","tag_path":[],"summary":"갈등 해소는 대립을 낳은 문제나 목표의 충돌이 해결되거나 더는 지속되지 않는 상태로 바뀌는 과정이다. 단순히 싸움이 멈춘 경우와 구분하고, 갈등의 원인이나 당사자 관계에 실질적인 변화가 생겼는지 확인한다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"갈등 해소","entry_url":"cards/ML-T00723/index.html"},{"id":"ML-T00724","row_version":4,"title":"대가 제시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00722","tag_path":[],"summary":"대가 제시는 선택이나 행동에 따르는 손실, 책임, 희생을 결과로 드러내는 방식이다. 막연한 위협이나 긴장만으로는 해당하지 않으며, 인물이나 공동체가 실제로 치러야 할 비용이 서사에 구체화되는지 본다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"대가 제시","entry_url":"cards/ML-T00724/index.html"},{"id":"ML-T00725","row_version":2,"title":"보상 제공","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00722","tag_path":[],"summary":"보상 제공은 인물의 노력이나 선택 뒤에 이익, 인정, 만족 같은 긍정적 결과를 돌려주는 방식이다. 우연히 얻은 이득과 구별해 앞선 행동과 보상 사이에 서사적 연관이 있는지 살핀다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"보상 제공","entry_url":"cards/ML-T00725/index.html"},{"id":"ML-T00726","row_version":3,"title":"질서 복구","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00722","tag_path":[],"summary":"질서 복구는 위기나 혼란으로 흔들린 규칙, 관계, 공동체의 안정이 다시 자리 잡는 전개다. 이전 상태가 그대로 돌아왔는지만 보지 말고, 복구된 질서가 누구에게 유효하며 어떤 변화나 비용을 남겼는지도 확인한다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"질서 복구","entry_url":"cards/ML-T00726/index.html"},{"id":"ML-T00727","row_version":3,"title":"다음 사건 연결","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00722","tag_path":[],"summary":"다음 사건 연결은 현재 사건의 결과나 남은 문제를 계기로 후속 사건이 시작되도록 전개를 잇는 방식이다. 시간상 다음 장면이 이어지는 것만으로는 부족하며, 앞선 사건이 다음 사건의 원인이나 동기가 되는지 판단한다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"다음 사건 연결","entry_url":"cards/ML-T00727/index.html"},{"id":"ML-T00728","row_version":2,"title":"속편 예고","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":"tag","parent_id":"ML-T00722","tag_path":[],"summary":"속편 예고는 현재 작품 안에 미해결 위협, 새로운 인물, 후속 과제 등을 남겨 이후 작품의 가능성을 암시하는 장치다. 일반적인 열린 결말이나 다음 장면을 위한 복선과 구분해, 현재 이야기 밖의 후속 작품을 기대하게 하는 신호인지 살핀다.","accent":"#88734E","tab":"#79866C","facet":"서사 기능","bookmark":"속편 예고","entry_url":"cards/ML-T00728/index.html"},{"id":"ML-T00729","row_version":4,"title":"만남·분리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"group","parent_id":"ML-F07","tag_path":[],"summary":"인물들이 만나거나 서로 떨어져 관계와 사건의 흐름이 바뀌는 일련의 장면을 가리킨다. 단순한 거리 변화보다 만남이나 분리가 서사에 의미 있는 전환을 만드는 경우에 적용한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"만남·분리","entry_url":"cards/ML-T00729/index.html"},{"id":"ML-T00730","row_version":2,"title":"첫 만남","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"서로 알지 못했거나 관계가 없던 인물들이 처음 마주치고 상호작용을 시작하는 사건이다. 이미 알고 지내던 인물의 재등장이나 단순한 같은 공간에의 출현과 구별한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"첫 만남","entry_url":"cards/ML-T00730/index.html"},{"id":"ML-T00731","row_version":2,"title":"재회","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"떨어져 지내거나 연락이 끊겼던 인물들이 다시 만나 관계를 이어 가는 사건이다. 처음 대면하는 장면이나 과거 관계의 정리만을 위한 작별에는 적용하지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"재회","entry_url":"cards/ML-T00731/index.html"},{"id":"ML-T00732","row_version":2,"title":"이별","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"인물들이 헤어져 당분간 또는 영구히 함께하지 못하게 되는 사건이나 장면이다. 관계를 끝내겠다는 결정 자체보다 물리적 이별이나 작별의 순간에 초점을 둔다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"이별","entry_url":"cards/ML-T00732/index.html"},{"id":"ML-T00733","row_version":2,"title":"실종","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"인물이나 대상이 예상치 못하게 사라지고 행방을 알 수 없게 되는 상태 또는 사건이다. 죽음이 확인되었거나 자발적으로 떠난 사실이 분명한 경우와 구별한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"실종","entry_url":"cards/ML-T00733/index.html"},{"id":"ML-T00734","row_version":3,"title":"추방","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"권한을 가진 집단이나 인물이 누군가에게 특정 장소나 공동체를 떠나도록 강제하는 처분이다. 자발적 이주나 잠시 자리를 피하는 행동과 달리 강제성과 배제의 결정이 핵심이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"추방","entry_url":"cards/ML-T00734/index.html"},{"id":"ML-T00735","row_version":3,"title":"귀환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"떠났거나 쫓겨났던 인물이 이전의 장소나 공동체로 돌아오는 사건이다. 처음으로 새로운 곳에 도착하는 일이나 돌아오려는 의도만으로는 해당하지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"귀환","entry_url":"cards/ML-T00735/index.html"},{"id":"ML-T00736","row_version":2,"title":"합류","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"기존에 활동하던 인물이나 집단에 새 인물이 들어와 공동의 목적이나 활동을 함께하게 되는 일이다. 같은 장소에 나타나는 것만으로는 부족하며 소속이나 협력이 형성되어야 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"합류","entry_url":"cards/ML-T00736/index.html"},{"id":"ML-T00737","row_version":2,"title":"결별","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"tag","parent_id":"ML-T00729","tag_path":[],"summary":"인물들이 관계나 공동의 활동을 끝내기로 하고 각자의 길을 가는 결정 또는 사건이다. 일시적으로 자리를 비우는 이별과 구별하며, 관계의 종료가 중심일 때 적용한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"결별","entry_url":"cards/ML-T00737/index.html"},{"id":"ML-T00738","row_version":2,"title":"탐색·발견","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":"group","parent_id":"ML-F07","tag_path":[],"summary":"알려지지 않은 장소나 정보에 접근해 대상을 찾아내고 새로운 사실을 알아내는 행동이다. 대상의 위치를 찾는 과정과 발견으로 드러난 결과를 구분해 적용한다.","accent":"#9B7160","tab":"#778F70","facet":"사건·행동","bookmark":"탐색·발견","entry_url":"cards/ML-T00738/index.html"}]}.cards;